import {modules,statuses} from './modules.mjs';

export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(f,key,label)=>esc(f[key]?.trim()||`[${label}]`);
const para=value=>String(value||'').split(/\n+/).filter(Boolean).map(x=>`<p>${esc(x)}</p>`).join('');
const table=(headers,rows,cls='')=>rows.length?`<table class="${cls}"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`:`<p class="empty-line">No project records have been added to this schedule.</p>`;
const listTable=(project,key)=>{const rows=structuredClone(project.lists[key]||[]),enabled=id=>project.moduleStates[id]!=='not_applicable';
  if(key==='uses'&&enabled('fourD'))rows.push({name:'4D construction planning',status:project.moduleStates.fourD,owner:project.fields.contractor,output:'Sequence review and agreed 4D package'});
  if(key==='uses'&&enabled('fiveD'))rows.push({name:'5D / quantity take-off',status:project.moduleStates.fiveD,owner:project.fields.contractor,output:'Agreed quantities / cost-linked outputs'});
  if(key==='deliverables'&&enabled('fourD'))rows.push({title:'4D sequence and review package',producer:project.fields.contractor,date:'To be agreed',format:'Native / video',acceptance:'Agreed review record'});
  if(key==='deliverables'&&enabled('assets'))rows.push({title:'Asset information',producer:'Relevant suppliers / task teams',date:'Handover milestones',format:project.fields.assetSchema||'Schema to be agreed',acceptance:'Validated against AIR'});
  if(key==='deliverables'&&enabled('cobie'))rows.push({title:'COBie deliverable',producer:project.fields.contractor,date:'Agreed data drops',format:project.fields.cobieVersion||'COBie version to be agreed',acceptance:'Schema and content validation'});
  const config={
    parties:[['Organization','Project role','Code','Responsibility'],['name','role','code','responsibility']],
    team:[['Name','Organization','Role','Contact'],['name','organization','role','email']],
    responsibilities:[['Activity / deliverable','Responsible','Accountable','Consulted','Informed'],['activity','responsible','accountable','consulted','informed']],
    references:[['Reference','Code','Revision','Status','Source'],['title','code','revision','status','source']],
    uses:[['BIM use','Status','Owner','Output'],['name','status','owner','output']],
    software:[['Purpose','Product','Version','Exchange format'],['use','product','version','exchange']],
    exchanges:[['Exchange','Milestone','Sender','Receiver','Format','Status'],['exchange','milestone','sender','receiver','format','status']],
    models:[['Model code','Discipline','Building / zone','Producer'],['code','discipline','zone','producer']],
    namingFields:[['Order','Field','Permitted values / code list','Example'],['order','field','codeList','example']],
    loin:[['Element / system','Milestone','Geometry','Alphanumeric information','Documentation','Responsible party'],['element','milestone','geometry','information','documentation','responsible']],
    milestones:[['Milestone','Stage gate','Date','Outputs'],['name','gate','date','output']],
    deliverables:[['Deliverable','Producer','Date','Format','Acceptance criteria'],['title','producer','date','format','acceptance']],
    clashes:[['Test','Selection A','Selection B','Type','Tolerance / clearance','Owner'],['name','setA','setB','type','tolerance','owner']],
    meetings:[['Meeting','Frequency','Participants','Output'],['name','frequency','participants','output']],
    qaChecks:[['Check','Frequency','Checker','Acceptance criterion','Evidence'],['check','frequency','checker','acceptance','evidence']],
    assetRequirements:[['Asset / system','Required property','Source','Milestone','Format','Responsible party'],['asset','property','source','milestone','format','responsible']],
    decisions:[['Reference','Subject','Decision / assumption','Owner','Due date','Status'],['reference','subject','decision','owner','dueDate','status']],
    appendices:[['Appendix','Reference','Status','File / link'],['title','reference','status','location']]
  }[key];return table(config[0],rows.map(row=>config[1].map(k=>row[k]||'')),['clashes','loin','assetRequirements','decisions','exchanges'].includes(key)?'wide':'');};
const kv=rows=>`<table class="key-values"><tbody>${rows.map(([k,v])=>`<tr><th>${esc(k)}</th><td>${v}</td></tr>`).join('')}</tbody></table>`;
const bullets=items=>`<ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;

function moduleBody(id,p){
  const f=p.fields,c=val(f,'contractor','Main contractor'),client=val(f,'client','Client / Employer'),consultant=val(f,'consultant','Supervision consultant'),project=val(f,'projectName','Project name');
  const content={
    overview:()=>`<p>This Post-Contract BIM Execution Plan defines the proposed information management, production and coordination arrangements for <strong>${project}</strong>. It is prepared by <strong>${c}</strong> for review with <strong>${consultant}</strong> and agreement with <strong>${client}</strong>.</p>${kv([['Project reference',val(f,'projectCode','Project code')],['Location',val(f,'location','Location')],['Sector',val(f,'sector','Sector')],['Contract reference',val(f,'contractNumber','Contract number')],['Main contractor',c],['Client / Employer',client],['Supervision consultant',consultant],['Designer',val(f,'designer','Designer')]])}<h3>Project description</h3>${para(f.description)||'<p>[Project description and appointed works]</p>'}<p>This document is project-specific and must be read with the referenced appointment and information requirements. Generic provisions do not override contract documents.</p>`,
    scope:()=>`${kv([['Contract type',val(f,'contractType','Contract type')],['Design responsibility',val(f,'designResponsibility','Design responsibility')],['Information management role',val(f,'informationRole','Information management role')],['Drawing production strategy',val(f,'drawingStrategy','Drawing strategy')]])}<h3>Coordination scope</h3>${para(f.coordinationScope)}<h3>Exclusions and interfaces</h3>${para(f.exclusions)||'<p>[Record exclusions, boundaries and interfaces requiring another party’s action.]</p>'}<p>The designation of main contractor does not by itself transfer design, acceptance or information-authority duties beyond the appointment.</p>`,
    references:()=>`<p>Only references recorded below are treated as project inputs. Client requirements are applied with their exact revision and adoption status; reference material is not automatically converted into a contractual requirement.</p>${listTable(p,'references')}<h3>Decision and assumption register</h3>${listTable(p,'decisions')}<p>Missing or conflicting requirements remain visible until resolved by the authorized party and recorded with an owner and status.</p>`,
    governance:()=>`<p>${c} will maintain project BIM governance within its appointed scope and coordinate interfaces between the relevant production teams.</p>${listTable(p,'parties')}<h3>Project team</h3>${listTable(p,'team')}<h3>Responsibility matrix</h3>${listTable(p,'responsibilities')}<h3>Core responsibility principles</h3>${bullets(['Each producing team is responsible for the quality and completeness of its information.','Review does not relieve the originator of responsibility.','Acceptance authority and design approval follow the appointment and agreed workflow.','Changes to responsibilities are recorded with an owner, source and effective revision.'])}`,
    uses:()=>`<p>The selected BIM uses are planned against a defined purpose, owner and output. Their inclusion in this draft does not by itself constitute client acceptance.</p>${listTable(p,'uses')}`,
    cde:()=>`${kv([['Coordination CDE',val(f,'cde','CDE platform')],['CDE location',val(f,'cdeUrl','CDE URL')],['Formal submission platform',val(f,'submissionPlatform','Submission platform')],['Worksharing method',val(f,'worksharingMode','Worksharing mode')],['Information states',val(f,'informationStates','Information states')],['Suitability / purpose codes',val(f,'suitabilitySystem','Suitability system')]])}<h3>Review and authorization</h3>${para(f.reviewWorkflow)}<p>Folder names, access groups, suitability codes and response codes must be confirmed for the project. No owner-specific convention is assumed unless listed as an adopted reference.</p>`,
    information:()=>`${bullets(['Information is developed in the producing team’s controlled work area.','Information is checked before it is shared for a stated purpose.','Every exchange identifies originator, revision, issue date, status and permitted use.','Published information follows the agreed authorization and acceptance route.','Superseded information is retained in the archive according to the project procedure.'])}<h3>Information exchange schedule</h3>${listTable(p,'exchanges')}<p>Exchanges use the formats, versions and dates recorded in the software and delivery schedules. Changes are communicated before the next affected exchange.</p>`,
    security:()=>`${kv([['Backup location',val(f,'backupLocation','Backup location')],['Backup frequency',val(f,'backupFrequency','Backup frequency')],['Retention period',val(f,'retention','Retention period')]])}<p>Access is granted on the principle of least privilege. Project information is stored only in approved locations. Recovery arrangements identify the responsible party and are tested at an agreed interval.</p>`,
    software:()=>`<p>Project software and versions are selected for a defined use. Upgrades are coordinated before exchange to avoid incompatibility or loss of information.</p>${listTable(p,'software')}<p>Native and exchange formats are agreed for each deliverable. The receiving party verifies that the information can be used for its stated purpose.</p>`,
    breakdown:()=>`<p>Models are divided by discipline, building, zone and production responsibility to support manageable authoring, review and federation. Model counts are generated from the approved register and are not fixed by this template.</p>${listTable(p,'models')}<h3>Federation</h3><p>${c} will define federation groups, exchange scope and the responsible aggregator. Links and external references not intended for an exchange are excluded or controlled before issue.</p>`,
    naming:()=>`${kv([['File naming pattern',val(f,'namingPattern','Naming pattern')],['Originator code',val(f,'originatorCode','Originator code')]])}<p>Permitted values, separators, field lengths and sequence numbering are maintained in an approved project code list. Examples are generated from project codes and are checked before issue.</p>${listTable(p,'namingFields')}<p class="example">Example structure: ${val(f,'namingPattern','PROJECT-ORIGINATOR-VOLUME-LEVEL-TYPE-ROLE-NUMBER')}</p>`,
    coordinates:()=>`${kv([['Coordinate reference system',val(f,'crs','CRS')],['Vertical datum',val(f,'verticalDatum','Vertical datum')],['Authoring units',val(f,'units','Units')],['Unified reference / survey',val(f,'ursReference','URS reference')],['North rotation',val(f,'northRotation','Angle and unit')]])}${bullets(['Confirm the authorized survey and reference revision before initial model exchange.','Record how shared coordinates are acquired and verified in every authoring platform.','Check grids, levels, units and rotation when a new model or reference revision enters the federation.','Do not move an established project reference without an approved change record.'])}`,
    loin:()=>`${kv([['LOIN / LOD framework',val(f,'loinSystem','Framework and revision')],['Classification system',val(f,'classification','Classification system and revision')]])}<p>Geometry, alphanumeric information and documentation requirements are defined by purpose, element group and delivery milestone. A model-development label alone does not define every required property or document.</p>${listTable(p,'loin')}`,
    authoring:()=>`${kv([['Worksharing mode',val(f,'worksharingMode','Worksharing mode')],['Drawing strategy',val(f,'drawingStrategy','Drawing strategy')],['Model size limit',val(f,'modelSizeLimit','Limit and source')]])}<h3>Project authoring procedure</h3>${para(f.authoringProcedure)||'<p>[Record agreed worksets, views, templates, linking, browser organization and issue-sheet controls.]</p>'}${bullets(['Use approved templates and shared project resources.','Maintain links, coordinates and model scope before exchange.','Produce drawings in discipline or production models according to the selected strategy.','Remove unnecessary views and data only through the agreed maintenance procedure.'])}`,
    quality:()=>`${kv([['QA/QC frequency',val(f,'qaFrequency','QA/QC frequency')],['Warnings policy',val(f,'warningPolicy','Warnings policy')],['Model size limit',val(f,'modelSizeLimit','Limit and source')]])}${bullets(['Check file naming, project information, model scope and exchange format.','Check coordinates, levels, grids and linked information.','Review model health, warnings and duplicate or unplaced content.','Validate required properties and classification against the applicable milestone.','Record check result, checker, date, revision and corrective action.'])}<h3>QA/QC schedule</h3>${listTable(p,'qaChecks')}`,
    coordination:()=>`${kv([['Coordination cycle',val(f,'coordinationCycle','Coordination cycle')],['Issue platform',val(f,'issuePlatform','Issue platform')]])}<h3>Clash and clearance matrix</h3>${listTable(p,'clashes')}<h3>Issue workflow</h3>${para(f.issueWorkflow)}<p>Tests distinguish physical intersections from clearance requirements. Tolerances, units, exclusions and priorities require a stated source or project decision. Accepted intersections retain their justification and approval.</p>`,
    meetings:()=>`${listTable(p,'meetings')}<p>Meeting outputs record decisions, responsible parties and due dates. The issue register and delivery plan are updated from agreed actions rather than maintained as disconnected records.</p>`,
    delivery:()=>`<h3>Project milestones</h3>${listTable(p,'milestones')}<h3>Information deliverables</h3>${listTable(p,'deliverables')}<p>The MIDP consolidates the relevant task information delivery plans. Each entry identifies the producer, date, format, information requirement and acceptance criterion.</p>`,
    fourD:()=>`${kv([['Approved programme source',val(f,'programmeSource','Programme and revision')],['4D tool',val(f,'fourDTool','Product and version')]])}${bullets(['Confirm the programme revision and model scope for each cycle.','Use documented activity identifiers or selection rules for model linkage.','Review sequence logic and interfaces with planning and construction teams.','Issue agreed native, video and review records according to the delivery plan.'])}`,
    fiveD:()=>`${kv([['5D / QTO tool',val(f,'fiveDTool','Product and version')]])}<p>Measurement purpose, model status, element scope, classification, cost-code mapping and rules of measurement are confirmed before quantity extraction. Quantity take-off may be required independently of cost integration.</p>`,
    existing:()=>`<p>Existing-condition information is accepted only with its source, date, accuracy, limitations and authorized use recorded. Where survey or scanning is required, the method, coordinate control, coverage and verification criteria are agreed before capture.</p>`,
    fabrication:()=>`<p>Fabrication information is produced only for the defined systems and by the responsible specialist. Required geometry, connections, tolerances, machine or exchange formats, review route and responsibility for fabrication decisions are recorded in the delivery plan.</p>`,
    visualization:()=>`<p>Visualization, virtual reality and other presentation outputs are defined by purpose, audience, source model status, tool, update frequency and deliverable. Visual outputs do not replace technical approval records.</p>`,
    asbuilt:()=>`${kv([['Verification method',val(f,'asBuiltMethod','Verification method')],['Required accuracy',val(f,'asBuiltAccuracy','Accuracy and unit')]])}${bullets(['Use approved drawings, responses, site changes and verified red-line records as controlled inputs.','Assign each update to the responsible production team.','Verify the submitted condition against the agreed information requirements.','Identify outstanding items and retain evidence of closure.'])}`,
    assets:()=>`${kv([['Asset data schema',val(f,'assetSchema','Schema and revision')]])}<p>Asset scope, required properties, supplier responsibilities, identifiers and validation rules are defined independently of the chosen exchange format. COBie is one possible format and is not automatically required.</p>${listTable(p,'assetRequirements')}`,
    cobie:()=>`${kv([['COBie version',val(f,'cobieVersion','COBie version')],['Asset data schema',val(f,'assetSchema','Asset schema')]])}<p>Required worksheets, data drops, property mapping, responsible suppliers, validation tool and acceptance criteria are agreed for each handover milestone.</p>`,
    tagging:()=>`<p>Asset identifiers are generated from the approved coding rule. The relationship between the physical label, model object, asset record and commissioning information is verified before handover.</p>`,
    handover:()=>`<p>${c} will consolidate the agreed handover package from verified production-team records.</p>${bullets(['As-built models and drawings in the agreed native and exchange formats.','Required asset and commissioning information.','Model, drawing and document indexes.','Outstanding-item register and acceptance evidence.','Archived source and issued records according to retention requirements.'])}<p>Handover acceptance follows the appointment and agreed criteria; file delivery alone is not evidence of acceptance.</p>`,
    appendices:()=>`${listTable(p,'appendices')}<p>Each appendix identifies whether it is embedded, linked or issued separately. Missing referenced material remains visible as an issue before formal release.</p>`
  };
  return (content[id]||(()=>'<p>Project-specific content to be confirmed.</p>'))();
}

export function buildDocument(project,review,logoUrl=''){
  const f=project.fields,include=m=>project.moduleStates[m.id]!=='not_applicable',active=modules.filter(include);
  const brand=logoUrl?`<img class="cover-logo" src="${esc(logoUrl)}" alt="Company logo">`:'<span>PROJECT INFORMATION DELIVERY</span>';
  const cover=project.style.cover?`<section class="cover page"><div class="cover-head">${brand}<b>WORKING ${review.ready?'REVIEW':'DRAFT'}</b></div><h1>BIM<br><strong>Execution</strong><br>Plan.</h1><p>Post-Contract / Main Contractor</p><div class="cover-rule"></div><h2>${val(f,'projectName','Project name')}</h2><p>${val(f,'projectCode','Project code')} · ${val(f,'location','Location')}</p>${kv([['Prepared for',val(f,'client','Client / Employer')],['Supervision consultant',val(f,'consultant','Consultant')],['Prepared by',val(f,'contractor','Main contractor')],['Document reference',val(f,'documentCode','Document number')],['Revision',val(f,'revision','Revision')],['Issue date',val(f,'issueDate','Issue date')]])}<div class="cover-foot"><span>PROJECT-SPECIFIC REVIEW REQUIRED</span><span>${review.ready?'READY FOR ISSUE REVIEW':'INCOMPLETE DRAFT'}</span></div></section>`:'';
  const releaseRows=project.releases.map(r=>[String(r.number),r.revision,r.issueDate,new Date(r.createdAt).toLocaleDateString('en-GB'),`${r.readiness}%`]);
  const templateRows=(project.appliedTemplates||[]).map(t=>[t.type==='client'?'Client requirements':'Company baseline',t.name,t.version,t.sourceReference||'Internal baseline',new Date(t.appliedAt).toLocaleDateString('en-GB')]);
  const prelim=`<section class="prelim page"><div class="running"><span>${val(f,'projectName','Project')}</span><span>${val(f,'documentCode','Document')} / ${val(f,'revision','Revision')}</span></div><span class="kicker">DOCUMENT CONTROL</span><h1>${val(f,'documentTitle','Post-Contract BIM Execution Plan')}</h1>${kv([['Document reference',val(f,'documentCode','Document number')],['Revision',val(f,'revision','Revision')],['Issue date',val(f,'issueDate','Issue date')],['Issue purpose',val(f,'issuePurpose','Purpose')],['Prepared by',val(f,'preparedBy','Name / role')],['Checked by',val(f,'checkedBy','Name / role')],['Approved by',val(f,'approvedBy','Name / role')]])}<h2>Revision history</h2>${releaseRows.length?table(['No.','Revision','Issue date','Frozen on','Readiness'],releaseRows):'<p class="empty-line">No frozen releases. This is a live working draft.</p>'}${templateRows.length?`<h2>Applied template register</h2>${table(['Type','Template','Version','Source','Applied'],templateRows)}`:''}${project.style.toc?`<h2>Contents</h2><ol class="toc">${active.map((m,i)=>`<li><a href="#m-${m.id}"><b>${String(i+1).padStart(2,'0')}</b><span>${esc(m.title)}</span><em>${statuses.find(s=>s.value===project.moduleStates[m.id])?.label||''}</em></a></li>`).join('')}</ol>`:''}</section>`;
  const notice=`<div class="doc-notice"><strong>${review.ready?'Ready for issue review.':'Incomplete working draft.'}</strong> ${review.critical} critical and ${review.warnings} advisory review items. Confirm project requirements, responsibilities and bracketed values before formal issue.</div>`;
  const sections=active.map((m,i)=>`<section class="doc-section" id="m-${m.id}"><div class="section-meta"><span>SECTION ${String(i+1).padStart(2,'0')}</span><span>${esc(project.moduleStates[m.id].replace('_',' '))}</span></div><h2>${i+1}. ${esc(m.title)}</h2>${moduleBody(m.id,project)}${project.notes[m.id]?.trim()?`<aside class="project-note"><strong>Project-specific provision</strong>${para(project.notes[m.id])}</aside>`:''}${project.moduleStates[m.id]==='pending'?'<p class="pending-note">Applicability remains pending project confirmation.</p>':''}</section>`).join('');
  const omitted=project.style.showNotApplicable?`<section class="doc-section"><h2>Not applicable modules</h2>${bullets(modules.filter(m=>!include(m)).map(m=>`${esc(m.title)} — excluded by project selection.`))}</section>`:'';
  return `${cover}<div class="document-body">${prelim}${notice}${sections}${omitted}<footer class="doc-end"><span>${val(f,'contractor','Main contractor')}</span><span>END OF DOCUMENT · ${val(f,'revision','Revision')}</span></footer></div>`;
}
